ng integration', 'cases': [{'input': [], 'expected': 'String ends with ";; Message size: <numBytes> bytes" where <numBytes> matches the value returned by Message.numBytes()', 'description': 'Regardless of the other branches, the final line must always be the message‑size line. This case verifies that the size suffix is correctly appended.'}, {'input': [], 'expected': 'String contains header, optional OPT pseudo‑section, optional TSIG line, four section headings (using the correct longString/updString variant), and the final size line, all separated by newlines as defined in the method.', 'description': 'Comprehensive scenario: OPT present, message signed and verified, opcode = UPDATE. This case ensures that **all** conditional branches are exercised in a single execution path.'}]}, {'group': 'OPT + TSIG combination', 'cases': [{'input': [], 'expected': 'String contains the header line from header.toStringWithRcode(...), followed by a blank line, the OPT pseudo‑section text, a newline, and then a line ";; TSIG invalid" followed by a newline.', 'description': 'Message has a non‑null OPT record, isSigned() returns true, and isVerified() returns false. Verifies that the method prints the OPT pseudo‑section and the TSIG line with the word "invalid".'}, {'input': [], 'expected': 'String contains the header line from header.toString() (no OPT block) and a line ";; TSIG ok" followed by a newline, with no "OPT" pseudo‑section present.', 'description': 'Message has no OPT record, isSigned() returns true, and isVerified() returns true. Checks that the TSIG ok line is emitted while the OPT block is omitted.'}]}, {'group': 'Header null safety', 'cases': [{'input': [], 'expected': 'Throws NullPointerException', 'description': 'Message.header is explicitly set to null before calling toString(). The method accesses header without a null‑check, so a NullPointerException is expected.'}]}, {'group': 'Section content rendering', 'cases': [{'input': [], 'expected': 'After the line ";; A